#!/usr/bin/env python3
"""AI-authored questions from visually inspected original page captures.

Review scope: cited spans, question clues, and the layouts of gichul pages 28–33.
The original images and enlarged inspection crops were read; this is not a
full-page OCR certification or a claim of human/expert review.
"""
import json, hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
SOURCES=json.loads((ROOT/'public/data/source-pages.json').read_text())['pages']
reviews=[];questions=[]
def page(n):return f'gyoyukron-gichul-page-{n}'
def captures(n):
 out=[]
 for c in SOURCES[page(n)]['captures']:
  assert hashlib.sha256((ROOT/'public'/c['src'].lstrip('/')).read_bytes()).hexdigest()==c['sha256']
  out.append({'src':c['src'],'sha256':c['sha256']})
 return out
def review(n,summary):reviews.append(dict(page=page(n),status='content',captures=captures(n),summary=summary))
def q(n,answer,prompt,quote,location,explain,aliases=None):
 index=1+sum(x['page']==page(n) for x in questions);c=captures(n)[0]
 questions.append(dict(id=f'gyoyukron-capture-practice-g{n}-late-{index}',page=page(n),kind='short',prompt=prompt,answer=answer,acceptedAnswers=aliases or [],evidence=[{'page':page(n),'quote':quote}],captureEvidence=[dict(**c,quote=quote,location=location)],explain=explain,topic=answer))

review(28,'인쇄 232~233쪽 감정이입과 3·1운동 수업안이다. 원본과 확대 사진에서 사고 활동 목록, 모둠별 연극, 평가표를 읽었다. 원 기출의 빈칸 요구 대신 수업의 표현 방식·평가 주체·상황 복원 단계를 구별한다.')
q(28,'극화 수업','3·1운동 자료를 조사한 학생들이 참가자와 일본군 등의 배역을 나누고 대본을 공연하는 수업 방식은?','이 두 가지를 활용한 대표적인 역사 수업 방법에는 극화 수업이 있다','오른쪽 233쪽 (가) 마지막 문장','역할을 맡아 대본으로 역사적 상황을 표현하는 극화 수업이다. 단순한 사실 암기와 구별하며 공연 전 자료 조사와 상황 파악이 제시된다.', ['극화 학습','극화식 수업','역할극 수업'])
q(28,'상호 평가','3·1운동 모둠별 공연을 마친 뒤 학생들이 체크리스트로 서로의 활동을 판단하도록 한 평가 방식은?','학생들의 상호 평가(체크리스트 활용)','오른쪽 233쪽 수업 사례 표 마지막 행','교사만 점수를 주는 것이 아니라 학생들이 서로의 활동을 평가하므로 상호 평가이다.', ['동료 평가'])
q(28,'상황의 맥락적 재구성','당시 사람들이 처한 제도·사회조건을 자료로 복원한 다음 그들의 행위를 이해하려는 활동을 왼쪽 사고 활동 목록의 용어로 쓰시오.','상황의 맥락적 재구성','왼쪽 232쪽 (가) 사고 활동 ②','행위자의 선택을 현재의 상식만으로 판단하지 않고 당시의 조건을 복원하는 활동이다.', ['맥락적 재구성'])

review(29,'인쇄 236~237쪽 역사적 설명 단원과 조선 후기 농업 변화 자료이다. 원본·확대 사진에서 사실을 묶는 개념의 성격, 시장 판매 작물, 소작인의 행동을 읽었다. 원 기출이 요구한 시대 전체 총괄명이나 평가기준 문장은 복제하지 않는다.')
q(29,'총괄개념','농업 기술의 변화·판매 작물 재배·노동 고용처럼 서로 다른 사실을 하나의 역사적 현상으로 묶어 이름 붙이는 개념을 무엇이라 하는가?','총괄개념(colligatory concept)으로 묶어서','오른쪽 237쪽 질문 1의 설명','여러 구체적 사실을 하나의 의미 있는 역사적 현상으로 묶는 것이 총괄개념의 역할이다. 여기서는 묶는 명칭의 정답 자체보다 개념의 기능을 구별한다.', ['총괄적 개념'])
q(29,'상업적 농업','농민이 자급용 생산을 넘어 시장에 팔 작물을 재배해 가계 수입을 늘리는 농업의 성격을 무엇이라 하는가?','농민들은 시장에 팔기 위한 작물을 재배하여 가계 수입을 증가시키기도 하였다','오른쪽 237쪽 자료 1 둘째 항목','시장 판매를 목적으로 생산하는 농업이므로 상업적 농업이다. 모든 조선 후기 농민이 이런 경영을 했다는 뜻은 아니다.', ['상업 농업'])
q(29,'소작쟁의','경작권을 확보하거나 지불할 소작료를 낮추기 위해 소작농들이 지주를 상대로 벌인 집단행동은?','소작쟁의를 벌여 경작권을 확보하거나 소작료를 낮추었다','오른쪽 237쪽 자료 2 조선사회의 변화','경작 조건을 둘러싼 소작인과 지주 사이의 분쟁이다. 사진의 자료는 경작권과 소작료를 구체적인 요구로 제시한다.')

review(30,'인쇄 250~251쪽 역사적 사고와 설명 모델이다. 오른쪽은 영국 정치 변화·조선 후기 학문 동향의 사례이고 왼쪽은 햄펠·드레이 비교이다. 초기 전제의 역할과 행위 목적에 주목하는 설명, 여러 학문 경향을 묶은 명칭을 읽었다. 오른쪽 영국 사건의 부정확한 1644년 표기는 사용하지 않았다.')
q(30,'초기 조건','햄펠의 설명에서 보편적 법칙과 함께 제시되어 개별 사건을 연역하는 출발점이 되는, 사건 이전의 구체적 사정을 무엇이라 하는가?','초기 조건을 제시하고 법칙을 제시하여 사건을 연역해 내는','왼쪽 250쪽 B 첫 부분','보편 법칙만으로 특정 사건을 설명할 수 없으므로 구체적인 초기 조건이 함께 필요하다. 법칙과 개별 전제를 구별하는 문항이다.')
q(30,'목적론적 설명','한 정치가의 행동을 그가 이루려던 목표와 선택한 수단의 관계로 이해할 때, 이 페이지가 사용하는 설명의 성격은 무엇인가?','행위자의 동기나 목적을 이해하는 데 초점을 맞추는 목적론적 설명이다','왼쪽 250쪽 B 중간','행위의 목표를 이해하는 데 초점을 맞추므로 목적론적 설명이다. 행위자가 지향한 목적을 이해하는 것은 그 행동을 도덕적으로 옳다고 인정하는 것과 구별된다.', ['목적론적 역사 설명'])
q(30,'실학운동','조선 후기 사회의 모순을 해결하려고 역사·지리 등 여러 분야의 연구가 전개된 경향을 사진의 사례는 어떤 이름으로 묶는가?','이러한 경향을 실학 운동이라고 한다','오른쪽 251쪽 보기 ㄴ 마지막 문장','서로 다른 연구 분야의 활동을 하나의 경향으로 묶은 이름을 읽는 문항이다. 개별 학자의 모든 학문을 동일한 단일 학파로 간주하는 것은 아니다.', ['실학'])

review(31,'인쇄 252~253쪽 행위설명이론과 할리치나 사단 자료 비교이다. 14번 사진도 직접 열어 오른쪽 기출만 재수록되었고 왼쪽은 다른 설명임을 확인했다. 14번의 새 정답인 합리적 설명·목표·보편법칙을 재사용하지 않고 신념, 서술 관점, 증거 평가를 읽었다. 논쟁적인 부대의 전모를 이 두 발췌만으로 사실 확정하지 않는다.')
q(31,'신념','행위 설명에서 어떤 사람이 원한 목표와 별개로 “이 방법이 조국을 지킬 수 있다고 믿었다”는 내용을 가리키는 용어는?','동기, 목적, 의도, 신념, 적절함','왼쪽 252쪽 기출 경향 분석 둘째 항목','신념은 행위자가 당시 무엇을 사실이거나 가능하다고 믿었는지를 뜻한다. 원하는 결과인 목표와 구별하며 그 믿음의 사실 여부나 도덕적 정당성까지 보증하지 않는다.')
q(31,'관점','같은 집단을 한 자료는 조국의 수호자로, 다른 자료는 전쟁 범죄자로 서술한다. 수업 설계가 서로 다르다고 명시한 서술의 시각은 무엇인가?','서로 다른 관점을 보여주는','오른쪽 253쪽 김 교사의 수업 설계 첫 문단','자료가 행위를 선택하고 평가하는 관점의 차이를 확인한다. 차이가 있다는 사실만으로 두 주장이 모두 참이거나 사실 확인이 불가능하다고 결론짓지 않는다.', ['서술 관점','역사적 관점'])
q(31,'증거','서로 다른 자료를 수집한 뒤 그 신뢰성과 관련성을 따져 결론의 근거로 쓸 수 있는지 검토할 때, 탐구 절차에서 가치 평가의 대상이 되는 것은?','증거의 가치 평가','오른쪽 253쪽 역사적 탐구력과 탐구 수업 설명','자료를 모으는 데서 끝내지 않고 그 자료가 주장을 뒷받침하는 증거로 적절한지 평가해야 한다. 자료의 관점 차이를 확인하는 활동과 증거 가치를 판단하는 활동은 구별된다.')

review(32,'인쇄 272~273쪽 영역고유 인지이론과 역사적 설명이다. 오른쪽은 30번 왼쪽과 같은 기출의 재수록이다. 왼쪽의 영역별 지식·선행지식 사례와 메타인지 보충설명을 원본·확대로 읽어 서로 다른 세 개념을 작성했다.')
q(32,'영역고유 인지이론','같은 연령 학생도 배운 역사 주제에 따라 추론 수준이 달라지는 현상을, 해당 교과의 지식 구조와 과제 특성을 고려해 이해하는 인지 이론은?','영역고유 인지이론(domain-specific cognitive theory)','왼쪽 272쪽 07번 도입 설명','연령에 따른 일반 단계만으로 역사 사고를 판단하지 않고 영역의 지식과 과제 특성을 고려한다.', ['영역 고유적 인지 이론'])
q(32,'선행지식','아프리카사를 이미 풍부하게 알고 있는 학생에게 여러 왕국의 흥망을 비교하는 과제를 주려 한다. 이 수업 설계가 활용한 학생의 기존 지식을 무엇이라 하는가?','아프리카 역사에 대한 선행 지식이 풍부한','왼쪽 272쪽 보기 ㄷ','새 과제에 앞서 학습자가 갖고 있는 지식이다. 영역고유 인지이론이라는 설명 틀과 실제 학습자의 지식 자원을 구별한다.')
q(32,'메타인지','역사 자료를 읽다가 “내가 이 내용을 정말 이해했는가”를 점검하고 독해 전략을 조절하는, 자신의 인지에 대한 인지 능력은?','자신의 생각이나 감정, 지식 등을 객관적으로 인지하고 조절하는 능력','왼쪽 272쪽 하단 Note 설명','자신의 이해 상태와 사고 전략을 점검·조절하는 메타인지이다. 특정 시대의 사실을 많이 알고 있는 선행지식과는 다른 기능이다.', ['상위인지','초인지'])

review(33,'인쇄 278~279쪽 아동 노동 자료를 활용하는 교사의 지식과 세계교역망 단원 설계이다. 원본·확대 사진에서 성취기준, 핵심 질문, 포토시 읽기 자료를 읽었다. 기존 기출의 슐만·와인버그 용어 답안을 복제하지 않고 수업 설계의 구성 요소와 탐구 대상을 묻는다.')
q(33,'성취기준','단원 설계에 앞서 (9역04-03)처럼 코드와 함께 제시되어 학습자가 설명할 수 있어야 할 도달 내용을 정하는 교육과정 문장은?','성취기준 선정','오른쪽 279쪽 학교 교육과정 및 교과서 분석 표 첫 행','학습자가 도달해야 할 내용을 진술하는 성취기준이다. 특정 교사가 만든 개별 수업 질문과 구별한다.')
q(33,'핵심 질문','“은의 도시에서는 무슨 일이 일어났나”처럼 단원 전체의 탐구를 이끌도록 두 예비 교사의 설계표가 맨 위에 둔 질문의 유형은?','핵심 질문','오른쪽 279쪽 예비 교사 1·2의 교육과정 설계 표','핵심 질문은 단원의 학습 내용을 관통하는 탐구 문제이다. 하위의 세부 질문과 연결하여 학습 활동을 조직한다.', ['핵심 탐구 질문'])
q(33,'포토시','세계교역망의 형성과 아메리카 원주민 노동을 탐구하는 수업에서, 거대한 은광과 연결하여 예비 교사 2가 핵심 질문에 넣은 도시는?','은의 도시 포토시에서는 무슨 일이 일어났나?','오른쪽 279쪽 예비 교사 2의 핵심 질문','사진의 수업안은 포토시 은광과 원주민 노동을 통해 세계교역망 형성의 영향을 탐구하도록 구성한다.')

if __name__=='__main__':
 target=ROOT/'tools/history-questions/capture-inputs/gyoyukron-gichul-late.json'
 target.write_text(json.dumps(dict(schemaVersion=1,subject='gyoyukron',reviews=reviews,questions=questions),ensure_ascii=False,indent=2)+'\n')
 print(len(reviews),'reviews;',len(questions),'questions')
